package com.legacycodes.smarthome.domain.model;

import java.util.Objects;

/**
 * Domain model for a single appliance.
 *
 * This is what the UI works with. It is NOT the DB entity — the entity
 * (ApplianceEntity) is how Room stores it. The mapper converts between them.
 *
 * Fields:
 *   id        — 0 when not yet saved; auto-generated by Room on insert
 *   deviceId  — foreign key to Device (the ESP32 this appliance lives on)
 *   name      — user-editable label, e.g. "Bedroom Light"
 *   type      — enum, drives the icon and future behavior
 *   gpioPin   — the physical pin on the ESP32
 *   room      — optional free-text room name; empty for now, used in Phase 6
 *   state     — last known logical state (1 = on, 0 = off)
 */
public class Appliance {

    private long id;
    private long deviceId;
    private String name;
    private ApplianceType type;
    private int gpioPin;
    private String room;
    private int state;

    public Appliance() {
        this.room = "";
        this.state = 0;
    }

    public Appliance(long id,
                     long deviceId,
                     String name,
                     ApplianceType type,
                     int gpioPin,
                     String room,
                     int state) {
        this.id = id;
        this.deviceId = deviceId;
        this.name = name;
        this.type = type;
        this.gpioPin = gpioPin;
        this.room = room != null ? room : "";
        this.state = state;
    }

    // ---- Getters / setters ----

    public long getId() { return id; }
    public void setId(long id) { this.id = id; }

    public long getDeviceId() { return deviceId; }
    public void setDeviceId(long deviceId) { this.deviceId = deviceId; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public ApplianceType getType() { return type; }
    public void setType(ApplianceType type) { this.type = type; }

    public int getGpioPin() { return gpioPin; }
    public void setGpioPin(int gpioPin) { this.gpioPin = gpioPin; }

    public String getRoom() { return room; }
    public void setRoom(String room) { this.room = room != null ? room : ""; }

    public int getState() { return state; }
    public void setState(int state) { this.state = state; }

    // ---- Convenience ----

    public boolean isOn() {
        return state == 1;
    }

    /** Short label shown under the name in the list, e.g. "Light · GPIO 5". */
    public String subtitle() {
        return type.getDisplayName() + " · GPIO " + gpioPin;
    }

    // ---- equals / hashCode (used by ListAdapter diffing in Phase 3) ----

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Appliance)) return false;
        Appliance that = (Appliance) o;
        return id == that.id
                && deviceId == that.deviceId
                && gpioPin == that.gpioPin
                && state == that.state
                && Objects.equals(name, that.name)
                && type == that.type
                && Objects.equals(room, that.room);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, deviceId, name, type, gpioPin, room, state);
    }

    @Override
    public String toString() {
        return "Appliance{" +
                "id=" + id +
                ", deviceId=" + deviceId +
                ", name='" + name + '\'' +
                ", type=" + type +
                ", gpioPin=" + gpioPin +
                ", room='" + room + '\'' +
                ", state=" + state +
                '}';
    }
}